import { useRouter, useParams } from 'next/navigation';
import Link from 'next/link';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Checkbox } from '@/components/ui/checkbox';
import { useToast } from '@/components/ui/use-toast';
import { Loader2 } from 'lucide-react';

export default function EditHomepageSectionPage() {
  const router = useRouter();
  const params = useParams();
  const { toast } = useToast();
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [categories, setCategories] = useState<{ _id: string; name: string }[]>([]);
  const [products, setProducts] = useState<{ _id: string; name: string }[]>([]);
  const [form, setForm] = useState({
    type: 'trending',
    image: '',
    title: '',
    subtitle: '',
    buttonText: '',
    link: '',
    image2: '',
    link2: '',
    active: true,
    order: 0,
    categoryId: '',
    linkedProductIds: [] as string[],
  });

  useEffect(() => {
    Promise.all([fetch('/api/categories').then((r) => r.json()), fetch('/api/products?limit=100').then((r) => r.json())]).then(
      ([cats, prods]) => {
        setCategories(Array.isArray(cats) ? cats : []);
        setProducts(Array.isArray(prods?.data) ? prods.data : []);
      }
    );
  }, []);

  useEffect(() => {
    const id = params.id as string;
    if (!id) return;
    fetch('/api/homepage-sections')
      .then((r) => r.json())
      .then((data) => {
        const s = data.find((x: any) => x._id === id);
        if (s) {
          setForm({
            type: s.type,
            title: s.title || '',
            image: s.image || '',
            link: s.link || '',
            image2: s.image2 || '',
            link2: s.link2 || '',
            linkedProductIds: (s.linkedProductIds || []).map((p: any) => (typeof p === 'object' ? p._id : p)),
            categoryId: s.categoryId?._id || s.categoryId || '',
            order: s.order ?? 0,
            active: s.active ?? true,
            subtitle: '',
            buttonText: '',
          });
        }
      })
      .catch(() => toast({ title: 'Failed to load section', variant: 'destructive' }))
      .finally(() => setLoading(false));
  }, [params.id]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setSaving(true);
    try {
      const res = await fetch(`/api/homepage-sections/${params.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          ...form,
          categoryId: form.categoryId || null,
        }),
      });
      if (res.ok) {
        toast({ title: 'Section updated' });
        router.push('/admin/homepage');
      } else {
        const err = await res.json();
        toast({ title: err.error || 'Failed', variant: 'destructive' });
      }
    } catch {
      toast({ title: 'Error', variant: 'destructive' });
    } finally {
      setSaving(false);
    }
  };

  const toggleProduct = (id: string) => {
    setForm((f) => ({
      ...f,
      linkedProductIds: f.linkedProductIds.includes(id)
        ? f.linkedProductIds.filter((x) => x !== id)
        : [...f.linkedProductIds, id],
    }));
  };

  const [uploading1, setUploading1] = useState(false);
  const [uploading2, setUploading2] = useState(false);

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>, fieldName: 'image' | 'image2', setUploadingLocal: (v: boolean) => void) => {
    const file = e.target.files?.[0];
    if (!file) return;
    try {
      setUploadingLocal(true);
      const fd = new FormData();
      fd.append('file', file);
      const res = await fetch('/api/upload', { method: 'POST', body: fd });
      const data = await res.json();
      if (data.url) {
        setForm((f) => ({ ...f, [fieldName]: data.url }));
      } else {
        toast({ title: 'Upload failed', variant: 'destructive' });
      }
    } catch (err) {
      toast({ title: 'Upload error', variant: 'destructive' });
    } finally {
      setUploadingLocal(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center py-20">
        <Loader2 className="h-8 w-8 animate-spin text-primary" />
      </div>
    );
  }

  return (
    <div className="max-w-2xl space-y-6">
      <h2 className="text-3xl font-bold">Edit Homepage Section</h2>
      <form onSubmit={handleSubmit}>
        <Card>
          <CardHeader>
            <CardTitle>Section config</CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div>
              <Label>Type</Label>
              <Select value={form.type} onValueChange={(v) => setForm((f) => ({ ...f, type: v }))}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="featured_categories">Featured Categories</SelectItem>
                  <SelectItem value="trending">Trending</SelectItem>
                  <SelectItem value="new_arrivals">New Arrivals</SelectItem>
                  <SelectItem value="promo">Promo</SelectItem>
                  <SelectItem value="category">Category Section</SelectItem>
                  <SelectItem value="big_size">Big Size (XL/XXL etc.)</SelectItem>
                  <SelectItem value="banner">Full Banner</SelectItem>
                  <SelectItem value="semi_banner">Semi Banner</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label>Title</Label>
              <Input
                value={form.title}
                onChange={(e) => setForm((f) => ({ ...f, title: e.target.value }))}
              />
              {form.type === 'big_size' && (
                <p className="text-sm text-muted-foreground mt-1">
                  Products with sizes XL, XXL, 2XL, 3XL, 4XL are shown automatically.
                </p>
              )}
            </div>
            {(form.type === 'trending' || form.type === 'new_arrivals' || form.type === 'category') && (
              <div>
                <Label>Linked products</Label>
                <div className="border rounded-lg p-3 max-h-48 overflow-y-auto space-y-2 mt-2">
                  {products.slice(0, 50).map((p) => (
                    <label key={p._id} className="flex items-center gap-2 cursor-pointer">
                      <input
                        type="checkbox"
                        checked={form.linkedProductIds.includes(p._id)}
                        onChange={() => toggleProduct(p._id)}
                      />
                      <span className="text-sm">{p.name}</span>
                    </label>
                  ))}
                </div>
              </div>
            )}
            {form.type === 'category' && (
              <div>
                <Label>Category</Label>
                <Select
                  value={form.categoryId}
                  onValueChange={(v) => setForm((f) => ({ ...f, categoryId: v }))}
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Select category" />
                  </SelectTrigger>
                  <SelectContent>
                    {categories.map((c) => (
                      <SelectItem key={c._id} value={c._id}>
                        {c.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            )}
            {(form.type === 'banner' || form.type === 'semi_banner') && (
              <>
                <div>
                  <Label>{form.type === 'semi_banner' ? 'Left Image *' : 'Image *'}</Label>
                  <div className="mt-2 border-2 border-dashed rounded-lg p-6 text-center">
                    <label className="cursor-pointer">
                      <input
                        type="file"
                        accept="image/*"
                        className="hidden"
                        onChange={(e) => handleFileSelect(e, 'image', setUploading1)}
                        disabled={uploading1}
                      />
                      {uploading1 ? (
                        <Loader2 className="h-8 w-8 animate-spin mx-auto" />
                      ) : form.image ? (
                        <img src={form.image} alt="Banner" className="max-h-40 mx-auto rounded" />
                      ) : (
                        <span className="text-sm text-muted-foreground">Click to upload image</span>
                      )}
                    </label>
                  </div>
                </div>
                <div>
                  <Label>Link (Optional URL)</Label>
                  <Input
                    value={form.link}
                    onChange={(e) => setForm((f) => ({ ...f, link: e.target.value }))}
                    placeholder="/products?category=..."
                  />
                </div>
              </>
            )}

            {form.type === 'semi_banner' && (
              <>
                <div className="pt-4 border-t">
                  <Label>Right Image *</Label>
                  <div className="mt-2 border-2 border-dashed rounded-lg p-6 text-center">
                    <label className="cursor-pointer">
                      <input
                        type="file"
                        accept="image/*"
                        className="hidden"
                        onChange={(e) => handleFileSelect(e, 'image2', setUploading2)}
                        disabled={uploading2}
                      />
                      {uploading2 ? (
                        <Loader2 className="h-8 w-8 animate-spin mx-auto" />
                      ) : form.image2 ? (
                        <img src={form.image2} alt="Semi Banner Right" className="max-h-40 mx-auto rounded" />
                      ) : (
                        <span className="text-sm text-muted-foreground">Click to upload 2nd image</span>
                      )}
                    </label>
                  </div>
                </div>
                <div>
                  <Label>Right Link (Optional URL)</Label>
                  <Input
                    value={form.link2}
                    onChange={(e) => setForm((f) => ({ ...f, link2: e.target.value }))}
                    placeholder="/products?category=..."
                  />
                </div>
              </>
            )}

            <div className="flex items-center gap-4">
              <div className="flex items-center space-x-2">
                <Checkbox
                  id="active"
                  checked={form.active}
                  onCheckedChange={(c) => setForm((f) => ({ ...f, active: !!c }))}
                />
                <Label htmlFor="active">Active</Label>
              </div>
              <div>
                <Label>Order</Label>
                <Input
                  type="number"
                  value={form.order}
                  onChange={(e) => setForm((f) => ({ ...f, order: parseInt(e.target.value, 10) || 0 }))}
                  className="w-24"
                />
              </div>
            </div>
          </CardContent>
        </Card>
        <div className="flex gap-4 mt-6">
          <Button type="submit" disabled={saving}>
            {saving && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
            Save
          </Button>
          <Button type="button" variant="outline" asChild>
            <Link href="/admin/homepage">Cancel</Link>
          </Button>
        </div>
      </form>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Checkbox } from '@/components/ui/checkbox';
import { useToast } from '@/components/ui/use-toast';
import { Loader2 } from 'lucide-react';

export default function NewHomepageSectionPage() {
  const router = useRouter();
  const { toast } = useToast();
  const [loading, setLoading] = useState(false);
  const [categories, setCategories] = useState<{ _id: string; name: string }[]>([]);
  const [products, setProducts] = useState<{ _id: string; name: string }[]>([]);
  const [form, setForm] = useState({
    type: 'trending',
    title: '',
    linkedProductIds: [] as string[],
    categoryId: '',
    image: '',
    link: '',
    image2: '',
    link2: '',
    order: 0,
    active: true,
  });

  useEffect(() => {
    Promise.all([fetch('/api/categories').then((r) => r.json()), fetch('/api/products?limit=100').then((r) => r.json())]).then(
      ([cats, prods]) => {
        setCategories(Array.isArray(cats) ? cats : []);
        setProducts(Array.isArray(prods?.data) ? prods.data : []);
      }
    );
  }, []);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    try {
      const res = await fetch('/api/homepage-sections', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          ...form,
          categoryId: form.categoryId || undefined,
        }),
      });
      if (res.ok) {
        toast({ title: 'Section created' });
        router.push('/admin/homepage');
      } else {
        const err = await res.json();
        toast({ title: err.error || 'Failed', variant: 'destructive' });
      }
    } catch {
      toast({ title: 'Error', variant: 'destructive' });
    } finally {
      setLoading(false);
    }
  };

  const toggleProduct = (id: string) => {
    setForm((f) => ({
      ...f,
      linkedProductIds: f.linkedProductIds.includes(id)
        ? f.linkedProductIds.filter((x) => x !== id)
        : [...f.linkedProductIds, id],
    }));
  };

  const [uploading1, setUploading1] = useState(false);
  const [uploading2, setUploading2] = useState(false);

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>, fieldName: 'image' | 'image2', setUploading: (v: boolean) => void) => {
    const file = e.target.files?.[0];
    if (!file) return;
    try {
      setUploading(true);
      const fd = new FormData();
      fd.append('file', file);
      const res = await fetch('/api/upload', { method: 'POST', body: fd });
      const data = await res.json();
      if (data.url) {
        setForm((f) => ({ ...f, [fieldName]: data.url }));
      } else {
        toast({ title: 'Upload failed', variant: 'destructive' });
      }
    } catch (err) {
      toast({ title: 'Upload error', variant: 'destructive' });
    } finally {
      setUploading(false);
    }
  };

  return (
    <div className="max-w-2xl space-y-6">
      <h2 className="text-3xl font-bold">Add Homepage Section</h2>
      <form onSubmit={handleSubmit}>
        <Card>
          <CardHeader>
            <CardTitle>Section config</CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div>
              <Label>Type</Label>
              <Select value={form.type} onValueChange={(v) => setForm((f) => ({ ...f, type: v }))}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="featured_categories">Featured Categories</SelectItem>
                  <SelectItem value="trending">Trending</SelectItem>
                  <SelectItem value="new_arrivals">New Arrivals</SelectItem>
                  <SelectItem value="promo">Promo</SelectItem>
                  <SelectItem value="category">Category Section</SelectItem>
                  <SelectItem value="big_size">Big Size (XL/XXL etc.)</SelectItem>
                  <SelectItem value="banner">Full Banner</SelectItem>
                  <SelectItem value="semi_banner">Semi Banner</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label>Title (section heading)</Label>
              <Input
                value={form.title}
                onChange={(e) => setForm((f) => ({ ...f, title: e.target.value }))}
                placeholder={form.type === 'big_size' ? 'e.g. Big Size' : 'e.g. Trending Now'}
              />
              {form.type === 'big_size' && (
                <p className="text-sm text-muted-foreground mt-1">
                  Products with sizes XL, XXL, 2XL, 3XL, 4XL are shown automatically.
                </p>
              )}
            </div>
            {(form.type === 'trending' || form.type === 'new_arrivals' || form.type === 'category') && (
              <div>
                <Label>Linked products (show these in this section)</Label>
                <div className="border rounded-lg p-3 max-h-48 overflow-y-auto space-y-2 mt-2">
                  {products.slice(0, 50).map((p) => (
                    <label key={p._id} className="flex items-center gap-2 cursor-pointer">
                      <input
                        type="checkbox"
                        checked={form.linkedProductIds.includes(p._id)}
                        onChange={() => toggleProduct(p._id)}
                      />
                      <span className="text-sm">{p.name}</span>
                    </label>
                  ))}
                </div>
              </div>
            )}
            {form.type === 'category' && (
              <div>
                <Label>Category (optional)</Label>
                <Select
                  value={form.categoryId}
                  onValueChange={(v) => setForm((f) => ({ ...f, categoryId: v }))}
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Select category" />
                  </SelectTrigger>
                  <SelectContent>
                    {categories.map((c) => (
                      <SelectItem key={c._id} value={c._id}>
                        {c.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            )}
            {(form.type === 'banner' || form.type === 'semi_banner') && (
              <>
                <div>
                  <Label>{form.type === 'semi_banner' ? 'Left Image *' : 'Image *'}</Label>
                  <div className="mt-2 border-2 border-dashed rounded-lg p-6 text-center">
                    <label className="cursor-pointer">
                      <input
                        type="file"
                        accept="image/*"
                        className="hidden"
                        onChange={(e) => handleFileSelect(e, 'image', setUploading1)}
                        disabled={uploading1}
                      />
                      {uploading1 ? (
                        <Loader2 className="h-8 w-8 animate-spin mx-auto" />
                      ) : form.image ? (
                        <img src={form.image} alt="Banner" className="max-h-40 mx-auto rounded" />
                      ) : (
                        <span className="text-sm text-muted-foreground">Click to upload image</span>
                      )}
                    </label>
                  </div>
                </div>
                <div>
                  <Label>Link (Optional URL)</Label>
                  <Input
                    value={form.link}
                    onChange={(e) => setForm((f) => ({ ...f, link: e.target.value }))}
                    placeholder="/products?category=..."
                  />
                </div>
              </>
            )}

            {form.type === 'semi_banner' && (
              <>
                <div className="pt-4 border-t">
                  <Label>Right Image *</Label>
                  <div className="mt-2 border-2 border-dashed rounded-lg p-6 text-center">
                    <label className="cursor-pointer">
                      <input
                        type="file"
                        accept="image/*"
                        className="hidden"
                        onChange={(e) => handleFileSelect(e, 'image2', setUploading2)}
                        disabled={uploading2}
                      />
                      {uploading2 ? (
                        <Loader2 className="h-8 w-8 animate-spin mx-auto" />
                      ) : form.image2 ? (
                        <img src={form.image2} alt="Semi Banner Right" className="max-h-40 mx-auto rounded" />
                      ) : (
                        <span className="text-sm text-muted-foreground">Click to upload 2nd image</span>
                      )}
                    </label>
                  </div>
                </div>
                <div>
                  <Label>Right Link (Optional URL)</Label>
                  <Input
                    value={form.link2}
                    onChange={(e) => setForm((f) => ({ ...f, link2: e.target.value }))}
                    placeholder="/products?category=..."
                  />
                </div>
              </>
            )}

            <div className="flex items-center gap-4">
              <div className="flex items-center space-x-2">
                <Checkbox
                  id="active"
                  checked={form.active}
                  onCheckedChange={(c) => setForm((f) => ({ ...f, active: !!c }))}
                />
                <Label htmlFor="active">Active</Label>
              </div>
              <div>
                <Label>Order</Label>
                <Input
                  type="number"
                  value={form.order}
                  onChange={(e) => setForm((f) => ({ ...f, order: parseInt(e.target.value, 10) || 0 }))}
                  className="w-24"
                />
              </div>
            </div>
          </CardContent>
        </Card>
        <div className="flex gap-4 mt-6">
          <Button type="submit" disabled={loading}>
            {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
            Create Section
          </Button>
          <Button type="button" variant="outline" asChild>
            <Link href="/admin/homepage">Cancel</Link>
          </Button>
        </div>
      </form>
    </div>
  );
}

'use client';

import { useEffect, useState } from 'react';
import { useRouter, useParams } from 'next/navigation';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Checkbox } from '@/components/ui/checkbox';
import { useToast } from '@/components/ui/use-toast';
import { Loader2, Upload, X } from 'lucide-react';

export default function EditProductPage() {
  const router = useRouter();
  const params = useParams();
  const { toast } = useToast();
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [uploadingImages, setUploadingImages] = useState(false);
  
  const [formData, setFormData] = useState({
    name: '',
    description: '',
    price: '',
    compareAtPrice: '',
    category: '',
    categoryId: '',
    sizes: [] as string[],
    colors: [] as string[],
    images: [] as string[],
    stock: '',
    featured: false,
  });

  const [sizes, setSizes] = useState<string[]>([]);
  const [categories, setCategories] = useState<{ _id: string; name: string; slug: string }[]>([]);
  const [homepageSections, setHomepageSections] = useState<{ _id: string; title: string; type: string; linkedProductIds: { _id: string }[] }[]>([]);
  const [showInSectionIds, setShowInSectionIds] = useState<string[]>([]);
  const COLORS = ['Black', 'White', 'Red', 'Blue', 'Green', 'Pink', 'Yellow', 'Purple'];

  const sectionTypesWithProducts = ['trending', 'new_arrivals', 'promo', 'category'];

  useEffect(() => {
    fetchProduct();
  }, []);

  useEffect(() => {
    fetch('/api/categories')
      .then((res) => res.ok ? res.json() : [])
      .then((data) => setCategories(Array.isArray(data) ? data : []))
      .catch(() => setCategories([]));
  }, []);

  // Sync categoryId from category name when editing old products that only have category string
  useEffect(() => {
    if (categories.length === 0 || !formData.category || formData.categoryId) return;
    const match = categories.find(
      (c) => c.name === formData.category || c.slug === formData.category
    );
    if (match) {
      setFormData((prev) => ({ ...prev, categoryId: match._id }));
    }
  }, [categories, formData.category, formData.categoryId]);

  useEffect(() => {
    fetch('/api/sizes')
      .then((res) => res.ok ? res.json() : [])
      .then((data) => setSizes(data.map((s: { name: string }) => s.name)))
      .catch(() => setSizes([]));
  }, []);

  useEffect(() => {
    fetch('/api/homepage-sections')
      .then((res) => res.ok ? res.json() : [])
      .then((data) => {
        const list = Array.isArray(data) ? data : [];
        const filtered = list.filter((s: { type: string }) => sectionTypesWithProducts.includes(s.type));
        setHomepageSections(filtered);
        const productId = typeof params.id === 'string' ? params.id : params.id?.[0];
        if (productId) {
          const included = filtered
            .filter((s: { linkedProductIds: { _id: string }[] }) =>
              (s.linkedProductIds || []).some((p: any) => (typeof p === 'object' ? p._id : p) === productId)
            )
            .map((s: { _id: string }) => s._id);
          setShowInSectionIds(included);
        }
      })
      .catch(() => setHomepageSections([]));
  }, [params.id]);

  const fetchProduct = async () => {
    try {
      const response = await fetch(`/api/products/${params.id}`);
      if (response.ok) {
        const data = await response.json();
        const catId = data.categoryId?.toString?.() || data.categoryId || '';
        const catName = data.category || '';
        setFormData({
          name: data.name,
          description: data.description,
          price: data.price.toString(),
          compareAtPrice: data.compareAtPrice?.toString() || '',
          category: catName,
          categoryId: catId,
          sizes: data.sizes,
          colors: data.colors,
          images: data.images,
          stock: data.stock.toString(),
          featured: data.featured,
        });
      } else {
        toast({
          title: 'Product not found',
          variant: 'destructive',
        });
        router.push('/admin/products');
      }
    } catch (error) {
      console.error('Failed to fetch product:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;

    setUploadingImages(true);

    try {
      const uploadPromises = Array.from(files).map(async (file) => {
        const formData = new FormData();
        formData.append('file', file);

        const response = await fetch('/api/upload', {
          method: 'POST',
          body: formData,
        });

        if (response.ok) {
          const data = await response.json();
          return data.url;
        }
        throw new Error('Upload failed');
      });

      const urls = await Promise.all(uploadPromises);
      setFormData((prev) => ({
        ...prev,
        images: [...prev.images, ...urls],
      }));

      toast({
        title: 'Images uploaded',
        description: `${urls.length} image(s) uploaded successfully`,
      });
    } catch (error) {
      toast({
        title: 'Upload failed',
        description: 'Failed to upload images',
        variant: 'destructive',
      });
    } finally {
      setUploadingImages(false);
    }
  };

  const handleRemoveImage = (index: number) => {
    setFormData((prev) => ({
      ...prev,
      images: prev.images.filter((_, i) => i !== index),
    }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setSaving(true);

    if (formData.images.length === 0) {
      toast({
        title: 'No images',
        description: 'Please upload at least one image',
        variant: 'destructive',
      });
      setSaving(false);
      return;
    }

    if (formData.sizes.length === 0) {
      toast({
        title: 'No sizes',
        description: 'Please select at least one size',
        variant: 'destructive',
      });
      setSaving(false);
      return;
    }

    try {
      const response = await fetch(`/api/products/${params.id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          ...formData,
          price: parseFloat(formData.price),
          compareAtPrice: formData.compareAtPrice ? parseFloat(formData.compareAtPrice) : undefined,
          stock: parseInt(formData.stock),
        }),
      });

      if (response.ok) {
        const productId = typeof params.id === 'string' ? params.id : params.id?.[0];
        if (productId) {
          for (const section of homepageSections) {
            const currentIds = (section.linkedProductIds || []).map((p: any) => (typeof p === 'object' ? p._id : p));
            const shouldInclude = showInSectionIds.includes(section._id);
            const hasProduct = currentIds.includes(productId);
            let newIds: string[];
            if (shouldInclude && !hasProduct) newIds = [...currentIds, productId];
            else if (!shouldInclude && hasProduct) newIds = currentIds.filter((id) => id !== productId);
            else continue;
            await fetch(`/api/homepage-sections/${section._id}`, {
              method: 'PUT',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ linkedProductIds: newIds }),
            });
          }
        }
        toast({
          title: 'Product updated',
          description: 'Product has been updated successfully',
        });
        router.push('/admin/products');
      } else {
        const data = await response.json();
        toast({
          title: 'Failed to update product',
          description: data.error,
          variant: 'destructive',
        });
      }
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to update product',
        variant: 'destructive',
      });
    } finally {
      setSaving(false);
    }
  };

  const toggleShowInSection = (sectionId: string) => {
    setShowInSectionIds((prev) =>
      prev.includes(sectionId) ? prev.filter((id) => id !== sectionId) : [...prev, sectionId]
    );
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center py-20">
        <Loader2 className="h-8 w-8 animate-spin text-primary" />
      </div>
    );
  }

  return (
    <div className="max-w-2xl">
      <h2 className="text-3xl font-bold mb-6">Edit Product</h2>

      <form onSubmit={handleSubmit} className="space-y-6">
        <Card>
          <CardHeader>
            <CardTitle>Basic Information</CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="name">Product Name *</Label>
              <Input
                id="name"
                value={formData.name}
                onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                required
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="description">Description *</Label>
              <textarea
                id="description"
                className="w-full min-h-[100px] rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                value={formData.description}
                onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                required
              />
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label htmlFor="price">Price (₹) *</Label>
                <Input
                  id="price"
                  type="number"
                  step="0.01"
                  value={formData.price}
                  onChange={(e) => setFormData({ ...formData, price: e.target.value })}
                  required
                />
              </div>

              <div className="space-y-2">
                <Label htmlFor="compareAtPrice">Compare at Price (₹)</Label>
                <Input
                  id="compareAtPrice"
                  type="number"
                  step="0.01"
                  value={formData.compareAtPrice}
                  onChange={(e) => setFormData({ ...formData, compareAtPrice: e.target.value })}
                />
              </div>
            </div>

            <div className="space-y-2">
              <Label htmlFor="category">Category *</Label>
              <Select
                value={formData.categoryId}
                onValueChange={(value) => {
                  const cat = categories.find((c) => c._id === value);
                  setFormData({ ...formData, categoryId: value, category: cat?.name ?? '' });
                }}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select category" />
                </SelectTrigger>
                <SelectContent>
                  {categories.map((c) => (
                    <SelectItem key={c._id} value={c._id}>
                      {c.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              {categories.length === 0 && (
                <p className="text-xs text-muted-foreground">No categories yet. Add them in Admin → Categories.</p>
              )}
            </div>

            <div className="space-y-2">
              <Label htmlFor="stock">Stock *</Label>
              <Input
                id="stock"
                type="number"
                value={formData.stock}
                onChange={(e) => setFormData({ ...formData, stock: e.target.value })}
                required
              />
            </div>

            <div className="flex items-center space-x-2">
              <Checkbox
                id="featured"
                checked={formData.featured}
                onCheckedChange={(checked) =>
                  setFormData({ ...formData, featured: checked as boolean })
                }
              />
              <Label htmlFor="featured" className="cursor-pointer">
                Featured Product
              </Label>
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle>Sizes *</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-3 gap-2">
              {sizes.map((size) => (
                <Button
                  key={size}
                  type="button"
                  variant={formData.sizes.includes(size) ? 'default' : 'outline'}
                  onClick={() => {
                    setFormData((prev) => ({
                      ...prev,
                      sizes: prev.sizes.includes(size)
                        ? prev.sizes.filter((s) => s !== size)
                        : [...prev.sizes, size],
                    }));
                  }}
                >
                  {size}
                </Button>
              ))}
            </div>
          </CardContent>
        </Card>

        {homepageSections.length > 0 && (
          <Card>
            <CardHeader>
              <CardTitle>Show on homepage</CardTitle>
              <p className="text-sm text-muted-foreground font-normal">Tick sections where this product should appear.</p>
            </CardHeader>
            <CardContent>
              <div className="flex flex-wrap gap-4">
                {homepageSections.map((section) => (
                  <div key={section._id} className="flex items-center space-x-2">
                    <Checkbox
                      id={`section-${section._id}`}
                      checked={showInSectionIds.includes(section._id)}
                      onCheckedChange={() => toggleShowInSection(section._id)}
                    />
                    <Label htmlFor={`section-${section._id}`} className="cursor-pointer text-sm font-normal">
                      {section.title || section.type}
                    </Label>
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>
        )}

        <Card>
          <CardHeader>
            <CardTitle>Colors *</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-2 gap-2">
              {COLORS.map((color) => (
                <div key={color} className="flex items-center space-x-2">
                  <Checkbox
                    id={color}
                    checked={formData.colors.includes(color)}
                    onCheckedChange={(checked) => {
                      setFormData((prev) => ({
                        ...prev,
                        colors: checked
                          ? [...prev.colors, color]
                          : prev.colors.filter((c) => c !== color),
                      }));
                    }}
                  />
                  <Label htmlFor={color} className="cursor-pointer">
                    {color}
                  </Label>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle>Images *</CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div>
              <Label htmlFor="images" className="cursor-pointer">
                <div className="border-2 border-dashed rounded-lg p-8 text-center hover:border-primary transition-colors">
                  {uploadingImages ? (
                    <Loader2 className="h-8 w-8 animate-spin mx-auto" />
                  ) : (
                    <>
                      <Upload className="h-8 w-8 mx-auto mb-2" />
                      <p className="text-sm text-muted-foreground">
                        Click to upload more images
                      </p>
                    </>
                  )}
                </div>
                <Input
                  id="images"
                  type="file"
                  multiple
                  accept="image/*"
                  className="hidden"
                  onChange={handleImageUpload}
                  disabled={uploadingImages}
                />
              </Label>
            </div>

            {formData.images.length > 0 && (
              <div className="grid grid-cols-4 gap-4">
                {formData.images.map((url, index) => (
                  <div key={index} className="relative aspect-square rounded-lg overflow-hidden border">
                    <img src={url} alt={`Product ${index + 1}`} className="object-cover w-full h-full" />
                    <button
                      type="button"
                      onClick={() => handleRemoveImage(index)}
                      className="absolute top-2 right-2 bg-destructive text-white rounded-full p-1"
                    >
                      <X className="h-4 w-4" />
                    </button>
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>

        <div className="flex gap-4">
          <Button type="submit" disabled={saving} className="flex-1">
            {saving && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
            Save Changes
          </Button>
          <Button
            type="button"
            variant="outline"
            onClick={() => router.back()}
          >
            Cancel
          </Button>
        </div>
      </form>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Checkbox } from '@/components/ui/checkbox';
import { useToast } from '@/components/ui/use-toast';
import { Loader2, Upload, X } from 'lucide-react';

export default function NewProductPage() {
  const router = useRouter();
  const { toast } = useToast();
  const [loading, setLoading] = useState(false);
  const [uploadingImages, setUploadingImages] = useState(false);
  
  const [formData, setFormData] = useState({
    name: '',
    description: '',
    price: '',
    compareAtPrice: '',
    category: '',
    categoryId: '',
    sizes: [] as string[],
    colors: [] as string[],
    images: [] as string[],
    stock: '',
    featured: false,
  });

  const [sizes, setSizes] = useState<string[]>([]);
  const [categories, setCategories] = useState<{ _id: string; name: string; slug: string }[]>([]);
  const [homepageSections, setHomepageSections] = useState<{ _id: string; title: string; type: string; linkedProductIds: { _id: string }[] }[]>([]);
  const [showInSectionIds, setShowInSectionIds] = useState<string[]>([]);
  const COLORS = ['Black', 'White', 'Red', 'Blue', 'Green', 'Pink', 'Yellow', 'Purple'];

  const sectionTypesWithProducts = ['trending', 'new_arrivals', 'promo', 'category'];

  useEffect(() => {
    fetch('/api/sizes')
      .then((res) => res.ok ? res.json() : [])
      .then((data) => setSizes(data.map((s: { name: string }) => s.name)))
      .catch(() => setSizes([]));
  }, []);

  useEffect(() => {
    fetch('/api/categories')
      .then((res) => res.ok ? res.json() : [])
      .then((data) => {
        const list = Array.isArray(data) ? data : [];
        setCategories(list);
        if (list.length > 0) {
          setFormData((prev) =>
            prev.categoryId ? prev : { ...prev, category: list[0].name, categoryId: list[0]._id }
          );
        }
      })
      .catch(() => setCategories([]));
  }, []);

  useEffect(() => {
    fetch('/api/homepage-sections')
      .then((res) => res.ok ? res.json() : [])
      .then((data) => {
        const list = Array.isArray(data) ? data : [];
        setHomepageSections(list.filter((s: { type: string }) => sectionTypesWithProducts.includes(s.type)));
      })
      .catch(() => setHomepageSections([]));
  }, []);

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;

    setUploadingImages(true);

    try {
      const uploadPromises = Array.from(files).map(async (file) => {
        const formData = new FormData();
        formData.append('file', file);

        const response = await fetch('/api/upload', {
          method: 'POST',
          body: formData,
        });

        if (response.ok) {
          const data = await response.json();
          return data.url;
        }
        throw new Error('Upload failed');
      });

      const urls = await Promise.all(uploadPromises);
      setFormData((prev) => ({
        ...prev,
        images: [...prev.images, ...urls],
      }));

      toast({
        title: 'Images uploaded',
        description: `${urls.length} image(s) uploaded successfully`,
      });
    } catch (error) {
      toast({
        title: 'Upload failed',
        description: 'Failed to upload images',
        variant: 'destructive',
      });
    } finally {
      setUploadingImages(false);
    }
  };

  const handleRemoveImage = (index: number) => {
    setFormData((prev) => ({
      ...prev,
      images: prev.images.filter((_, i) => i !== index),
    }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    if (formData.images.length === 0) {
      toast({
        title: 'No images',
        description: 'Please upload at least one image',
        variant: 'destructive',
      });
      setLoading(false);
      return;
    }

    if (formData.sizes.length === 0) {
      toast({
        title: 'No sizes',
        description: 'Please select at least one size',
        variant: 'destructive',
      });
      setLoading(false);
      return;
    }

    try {
      const response = await fetch('/api/products', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          ...formData,
          category: formData.category,
          categoryId: formData.categoryId || undefined,
          price: parseFloat(formData.price),
          compareAtPrice: formData.compareAtPrice ? parseFloat(formData.compareAtPrice) : undefined,
          stock: parseInt(formData.stock),
        }),
      });

      if (response.ok) {
        const created = await response.json();
        const newProductId = created._id;
        for (const sectionId of showInSectionIds) {
          const section = homepageSections.find((s) => s._id === sectionId);
          if (section) {
            const currentIds = (section.linkedProductIds || []).map((p: any) => (typeof p === 'object' ? p._id : p));
            if (!currentIds.includes(newProductId)) {
              await fetch(`/api/homepage-sections/${sectionId}`, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ linkedProductIds: [...currentIds, newProductId] }),
              });
            }
          }
        }
        toast({
          title: 'Product created',
          description: 'Product has been created successfully',
        });
        router.push('/admin/products');
      } else {
        const data = await response.json();
        toast({
          title: 'Failed to create product',
          description: data.error,
          variant: 'destructive',
        });
      }
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to create product',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const toggleShowInSection = (sectionId: string) => {
    setShowInSectionIds((prev) =>
      prev.includes(sectionId) ? prev.filter((id) => id !== sectionId) : [...prev, sectionId]
    );
  };

  return (
    <div className="max-w-2xl">
      <h2 className="text-3xl font-bold mb-6">Add New Product</h2>

      <form onSubmit={handleSubmit} className="space-y-6">
        <Card>
          <CardHeader>
            <CardTitle>Basic Information</CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="name">Product Name *</Label>
              <Input
                id="name"
                value={formData.name}
                onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                required
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="description">Description *</Label>
              <textarea
                id="description"
                className="w-full min-h-[100px] rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                value={formData.description}
                onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                required
              />
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label htmlFor="price">Price (₹) *</Label>
                <Input
                  id="price"
                  type="number"
                  step="0.01"
                  value={formData.price}
                  onChange={(e) => setFormData({ ...formData, price: e.target.value })}
                  required
                />
              </div>

              <div className="space-y-2">
                <Label htmlFor="compareAtPrice">Compare at Price (₹)</Label>
                <Input
                  id="compareAtPrice"
                  type="number"
                  step="0.01"
                  value={formData.compareAtPrice}
                  onChange={(e) => setFormData({ ...formData, compareAtPrice: e.target.value })}
                />
              </div>
            </div>

            <div className="space-y-2">
              <Label htmlFor="category">Category *</Label>
              <Select
                value={formData.categoryId}
                onValueChange={(value) => {
                  const cat = categories.find((c) => c._id === value);
                  setFormData({ ...formData, categoryId: value, category: cat?.name ?? '' });
                }}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select category" />
                </SelectTrigger>
                <SelectContent>
                  {categories.map((c) => (
                    <SelectItem key={c._id} value={c._id}>
                      {c.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              {categories.length === 0 && (
                <p className="text-xs text-muted-foreground">No categories yet. Add them in Admin → Categories.</p>
              )}
            </div>

            <div className="space-y-2">
              <Label htmlFor="stock">Stock *</Label>
              <Input
                id="stock"
                type="number"
                value={formData.stock}
                onChange={(e) => setFormData({ ...formData, stock: e.target.value })}
                required
              />
            </div>

            <div className="flex items-center space-x-2">
              <Checkbox
                id="featured"
                checked={formData.featured}
                onCheckedChange={(checked) =>
                  setFormData({ ...formData, featured: checked as boolean })
                }
              />
              <Label htmlFor="featured" className="cursor-pointer">
                Featured Product
              </Label>
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle>Sizes *</CardTitle>
          </CardHeader>
          <CardContent>
            {sizes.length === 0 ? (
              <p className="text-sm text-muted-foreground">Loading sizes…</p>
            ) : (
            <div className="grid grid-cols-3 gap-2">
              {sizes.map((size) => (
                <Button
                  key={size}
                  type="button"
                  variant={formData.sizes.includes(size) ? 'default' : 'outline'}
                  onClick={() => {
                    setFormData((prev) => ({
                      ...prev,
                      sizes: prev.sizes.includes(size)
                        ? prev.sizes.filter((s) => s !== size)
                        : [...prev.sizes, size],
                    }));
                  }}
                >
                  {size}
                </Button>
              ))}
            </div>
            )}
          </CardContent>
        </Card>

        {homepageSections.length > 0 && (
          <Card>
            <CardHeader>
              <CardTitle>Show on homepage</CardTitle>
              <p className="text-sm text-muted-foreground font-normal">Tick sections where this product should appear.</p>
            </CardHeader>
            <CardContent>
              <div className="flex flex-wrap gap-4">
                {homepageSections.map((section) => (
                  <div key={section._id} className="flex items-center space-x-2">
                    <Checkbox
                      id={`section-${section._id}`}
                      checked={showInSectionIds.includes(section._id)}
                      onCheckedChange={() => toggleShowInSection(section._id)}
                    />
                    <Label htmlFor={`section-${section._id}`} className="cursor-pointer text-sm font-normal">
                      {section.title || section.type}
                    </Label>
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>
        )}

        <Card>
          <CardHeader>
            <CardTitle>Colors *</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-2 gap-2">
              {COLORS.map((color) => (
                <div key={color} className="flex items-center space-x-2">
                  <Checkbox
                    id={color}
                    checked={formData.colors.includes(color)}
                    onCheckedChange={(checked) => {
                      setFormData((prev) => ({
                        ...prev,
                        colors: checked
                          ? [...prev.colors, color]
                          : prev.colors.filter((c) => c !== color),
                      }));
                    }}
                  />
                  <Label htmlFor={color} className="cursor-pointer">
                    {color}
                  </Label>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle>Images *</CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div>
              <Label htmlFor="images" className="cursor-pointer">
                <div className="border-2 border-dashed rounded-lg p-8 text-center hover:border-primary transition-colors">
                  {uploadingImages ? (
                    <Loader2 className="h-8 w-8 animate-spin mx-auto" />
                  ) : (
                    <>
                      <Upload className="h-8 w-8 mx-auto mb-2" />
                      <p className="text-sm text-muted-foreground">
                        Click to upload images
                      </p>
                    </>
                  )}
                </div>
                <Input
                  id="images"
                  type="file"
                  multiple
                  accept="image/*"
                  className="hidden"
                  onChange={handleImageUpload}
                  disabled={uploadingImages}
                />
              </Label>
            </div>

            {formData.images.length > 0 && (
              <div className="grid grid-cols-4 gap-4">
                {formData.images.map((url, index) => (
                  <div key={index} className="relative aspect-square rounded-lg overflow-hidden border">
                    <img src={url} alt={`Product ${index + 1}`} className="object-cover w-full h-full" />
                    <button
                      type="button"
                      onClick={() => handleRemoveImage(index)}
                      className="absolute top-2 right-2 bg-destructive text-white rounded-full p-1"
                    >
                      <X className="h-4 w-4" />
                    </button>
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>

        <div className="flex gap-4">
          <Button type="submit" disabled={loading} className="flex-1">
            {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
            Create Product
          </Button>
          <Button
            type="button"
            variant="outline"
            onClick={() => router.back()}
          >
            Cancel
          </Button>
        </div>
      </form>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { Trash2, Star, Loader2, Search, ExternalLink, Eye, EyeOff } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { useToast } from '@/components/ui/use-toast';
import Image from 'next/image';
import Link from 'next/link';

interface AdminReview {
    _id: string;
    productId: string;
    userId: string;
    userName: string;
    rating: number;
    title: string;
    body: string;
    createdAt: string;
    productName: string;
    productImage: string;
    productSlug: string;
    isHidden: boolean;
}

export default function AdminReviewsPage() {
    const { toast } = useToast();
    const [reviews, setReviews] = useState<AdminReview[]>([]);
    const [loading, setLoading] = useState(true);
    const [search, setSearch] = useState('');

    const fetchReviews = async () => {
        setLoading(true);
        try {
            const res = await fetch('/api/admin/reviews');
            const data = await res.json();
            if (res.ok) {
                setReviews(data.reviews || []);
            } else {
                throw new Error(data.error || 'Failed to fetch reviews');
            }
        } catch (err: any) {
            toast({
                title: 'Error',
                description: err.message,
                variant: 'destructive',
            });
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchReviews();
    }, []);

    const handleDelete = async (id: string) => {
        if (!confirm('Are you sure you want to delete this review? This action cannot be undone.')) {
            return;
        }
        try {
            const res = await fetch(`/api/reviews?id=${id}`, { method: 'DELETE' });
            if (!res.ok) throw new Error('Failed to delete review');
            toast({ title: 'Review deleted successfully' });
            setReviews(reviews.filter((r) => r._id !== id));
        } catch (err: any) {
            toast({ title: 'Error deleting review', variant: 'destructive' });
        }
    };

    const handleToggleHide = async (id: string, currentHidden: boolean) => {
        try {
            const res = await fetch('/api/admin/reviews', {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ id, isHidden: !currentHidden }),
            });

            if (!res.ok) throw new Error('Failed to update review visibility');

            setReviews(reviews.map(r => r._id === id ? { ...r, isHidden: !currentHidden } : r));

            toast({
                title: !currentHidden ? 'Review hidden' : 'Review visible',
                description: !currentHidden ? 'This review is now hidden from customers.' : 'This review is now visible to customers.'
            });
        } catch (err: any) {
            toast({ title: 'Error updating review', variant: 'destructive' });
        }
    };

    const filteredReviews = reviews.filter(
        (r) =>
            r.title.toLowerCase().includes(search.toLowerCase()) ||
            r.body.toLowerCase().includes(search.toLowerCase()) ||
            r.userName.toLowerCase().includes(search.toLowerCase()) ||
            r.productName.toLowerCase().includes(search.toLowerCase())
    );

    return (
        <div className="space-y-6">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
                <div>
                    <h1 className="text-2xl font-bold tracking-tight">Product Reviews</h1>
                    <p className="text-sm text-muted-foreground mt-1">
                        Manage customer reviews across all products
                    </p>
                </div>
            </div>

            {/* Toolbar */}
            <div className="flex flex-col sm:flex-row gap-4 items-center bg-card p-4 rounded-xl border border-border shadow-sm">
                <div className="relative w-full sm:max-w-md">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                    <input
                        type="text"
                        placeholder="Search reviews, products, or customers..."
                        value={search}
                        onChange={(e) => setSearch(e.target.value)}
                        className="w-full h-10 pl-9 pr-4 rounded-lg border border-border bg-background text-sm focus:outline-none focus:ring-2 focus:ring-primary/20 transition-all"
                    />
                </div>
                <div className="sm:ml-auto text-sm text-muted-foreground whitespace-nowrap">
                    {filteredReviews.length} Review{filteredReviews.length !== 1 ? 's' : ''}
                </div>
            </div>

            {/* Table */}
            <div className="rounded-xl border border-border bg-card overflow-hidden shadow-sm">
                <div className="overflow-x-auto">
                    <table className="w-full text-left text-sm whitespace-nowrap">
                        <thead className="bg-muted/50 border-b border-border">
                            <tr>
                                <th className="h-12 px-4 align-middle font-medium text-muted-foreground w-[250px]">Product</th>
                                <th className="h-12 px-4 align-middle font-medium text-muted-foreground w-[150px]">Customer</th>
                                <th className="h-12 px-4 align-middle font-medium text-muted-foreground min-w-[200px]">Rating & Review</th>
                                <th className="h-12 px-4 align-middle font-medium text-muted-foreground w-[120px]">Date</th>
                                <th className="h-12 px-4 align-middle font-medium text-muted-foreground w-[80px] text-right">Actions</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-border">
                            {loading ? (
                                <tr>
                                    <td colSpan={5} className="h-32 text-center p-4">
                                        <Loader2 className="h-6 w-6 animate-spin mx-auto text-muted-foreground" />
                                    </td>
                                </tr>
                            ) : filteredReviews.length === 0 ? (
                                <tr>
                                    <td colSpan={5} className="h-32 text-center text-muted-foreground p-4">
                                        {search ? 'No matching reviews found' : 'No reviews captured yet'}
                                    </td>
                                </tr>
                            ) : (
                                filteredReviews.map((review) => (
                                    <tr key={review._id} className="group hover:bg-muted/30 transition-colors">
                                        {/* Product */}
                                        <td className="p-4 align-middle">
                                            <div className="flex items-center gap-3">
                                                {review.productImage ? (
                                                    <div className="h-12 w-10 shrink-0 rounded-md overflow-hidden bg-muted border border-border">
                                                        <Image
                                                            src={review.productImage}
                                                            alt={review.productName}
                                                            width={40}
                                                            height={48}
                                                            className="h-full w-full object-cover"
                                                        />
                                                    </div>
                                                ) : (
                                                    <div className="h-12 w-10 shrink-0 rounded-md bg-muted border border-border" />
                                                )}
                                                <div className="min-w-0">
                                                    <p className="text-sm font-medium leading-tight line-clamp-2" title={review.productName}>
                                                        {review.productName}
                                                    </p>
                                                    <Link
                                                        href={`/products/${review.productSlug}`}
                                                        target="_blank"
                                                        className="inline-flex items-center text-xs text-primary hover:underline mt-1"
                                                    >
                                                        View Product <ExternalLink className="h-3 w-3 ml-1" />
                                                    </Link>
                                                </div>
                                            </div>
                                        </td>

                                        {/* Customer */}
                                        <td className="p-4 align-top">
                                            <div className="flex items-center gap-2 mt-1">
                                                <div className="h-7 w-7 rounded-full bg-primary/10 text-primary flex items-center justify-center text-xs font-bold shrink-0">
                                                    {review.userName.charAt(0).toUpperCase()}
                                                </div>
                                                <p className="text-sm font-medium line-clamp-1" title={review.userName}>
                                                    {review.userName}
                                                </p>
                                            </div>
                                        </td>

                                        {/* Review Content */}
                                        <td className="p-4 align-top max-w-[300px] whitespace-normal">
                                            <div className="space-y-1 py-1 max-w-sm">
                                                <div className="flex items-center gap-0.5">
                                                    {Array.from({ length: 5 }).map((_, i) => (
                                                        <Star
                                                            key={i}
                                                            className={`h-3.5 w-3.5 ${i < review.rating ? 'fill-amber-400 text-amber-400' : 'fill-muted text-muted-foreground/30'}`}
                                                        />
                                                    ))}
                                                </div>
                                                <p className="text-sm font-semibold">{review.title}</p>
                                                <p className="text-sm text-muted-foreground line-clamp-2 leading-relaxed" title={review.body}>
                                                    {review.body}
                                                </p>
                                            </div>
                                        </td>

                                        {/* Date */}
                                        <td className="p-4 align-top text-sm text-muted-foreground">
                                            <div className="mt-2">
                                                {new Date(review.createdAt).toLocaleDateString('en-US', {
                                                    month: 'short',
                                                    day: 'numeric',
                                                    year: 'numeric'
                                                })}
                                            </div>
                                        </td>

                                        {/* Actions */}
                                        <td className="p-4 align-top text-right">
                                            <div className="flex items-center justify-end gap-1 mt-1">
                                                <Button
                                                    variant="ghost"
                                                    size="icon"
                                                    className={`hover:bg-muted ${review.isHidden ? 'text-amber-500 hover:text-amber-600' : 'text-muted-foreground'} transition-all rounded-lg opacity-100 group-hover:bg-muted/50`}
                                                    onClick={() => handleToggleHide(review._id, review.isHidden)}
                                                    title={review.isHidden ? "Show Review" : "Hide Review"}
                                                >
                                                    {review.isHidden ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
                                                </Button>
                                                <Button
                                                    variant="ghost"
                                                    size="icon"
                                                    className="text-muted-foreground hover:text-destructive hover:bg-destructive/10 opacity-0 group-hover:opacity-100 transition-all rounded-lg"
                                                    onClick={() => handleDelete(review._id)}
                                                    title="Delete Review"
                                                >
                                                    <Trash2 className="h-4 w-4" />
                                                </Button>
                                            </div>
                                        </td>
                                    </tr>
                                ))
                            )}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
}

'use client';

import { useState, useEffect, useRef } from 'react';
import { useRouter } from 'next/navigation';
import { useSession } from 'next-auth/react';
import { isCustomerSession } from '@/lib/customerSession';
import { useCartStore } from '@/store/cartStore';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Separator } from '@/components/ui/separator';
import { formatPrice } from '@/lib/utils';
import { useToast } from '@/components/ui/use-toast';
import { Loader2, ChevronDown, Search, Plus, MapPin, Home, Briefcase, MoreHorizontal, Trash2, CheckCircle2 } from 'lucide-react';
import { INDIA_DATA } from '@/lib/locationData';
import OrderStatusPopup from '@/components/OrderStatusPopup';

/* ─── Types ──────────────────────────────────────────── */
interface SavedAddress {
  _id: string;
  label: 'Home' | 'Work' | 'Other';
  fullName: string;
  phone: string;
  email: string;
  street: string;
  city: string;
  state: string;
  zipCode: string;
  country: string;
  isDefault: boolean;
}

type FormData = {
  fullName: string;
  email: string;
  phone: string;
  street: string;
  state: string;
  city: string;
  zipCode: string;
  country: string;
};

const COUNTRIES = [
  { code: 'in', name: 'India' },
  { code: 'af', name: 'Afghanistan' },
  { code: 'au', name: 'Australia' },
  { code: 'bd', name: 'Bangladesh' },
