  { code: 'iq', name: 'Iraq' },
  { code: 'it', name: 'Italy' },
  { code: 'jp', name: 'Japan' },
  { code: 'ke', name: 'Kenya' },
  { code: 'my', name: 'Malaysia' },
  { code: 'mv', name: 'Maldives' },
  { code: 'mx', name: 'Mexico' },
  { code: 'mm', name: 'Myanmar' },
  { code: 'np', name: 'Nepal' },
