'use client';

import { useEffect, useState } from 'react';
import { useParams, useRouter } from 'next/navigation';
import Image from 'next/image';
import { ProductWithId } from '@/types';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Separator } from '@/components/ui/separator';
import { Heart, ShoppingCart, Loader2, Star } from 'lucide-react';
import { useCartStore } from '@/store/cartStore';
import { useWishlistStore } from '@/store/wishlistStore';
import { formatPrice } from '@/lib/utils';
import { useToast } from '@/components/ui/use-toast';
import { useSession } from 'next-auth/react';
import { isCustomerSession } from '@/lib/customerSession';
import ProductReviews from '@/components/ProductReviews';

export default function ProductDetailPage() {
  const params = useParams();
  const router = useRouter();
  const { data: session } = useSession();
  const { toast } = useToast();

  const [product, setProduct] = useState<ProductWithId | null>(null);
  const [loading, setLoading] = useState(true);
  const [selectedSize, setSelectedSize] = useState('');
  const [selectedImage, setSelectedImage] = useState(0);
  const [reviewStats, setReviewStats] = useState({ total: 0, avg: 0 });

  const addToCart = useCartStore((state) => state.addItem);
  const toggleWishlist = useWishlistStore((state) => state.toggleItem);
  const isInWishlist = useWishlistStore((state) =>
    product ? state.isInWishlist(product._id) : false
  );

  useEffect(() => {
    fetchProduct();
  }, [params.slug]);

  const fetchProduct = async () => {
    try {
      const response = await fetch(`/api/products/slug/${params.slug}`);
      if (response.ok) {
        const data = await response.json();
        setProduct(data);
        setSelectedSize(data.sizes[0] || '');

        // Fetch review stats
        try {
          const revRes = await fetch(`/api/reviews?productId=${data._id}`);
          if (revRes.ok) {
            const revData = await revRes.json();
            if (revData.stats) {
              setReviewStats(revData.stats);
            }
          }
        } catch {
          // ignore error, just don't show stats
        }
      } else {
        toast({
          title: 'Product not found',
          variant: 'destructive',
        });
        router.push('/products');
      }
    } catch (error) {
      console.error('Failed to fetch product:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleAddToCart = () => {
    if (!product) return;

    if (!selectedSize) {
      toast({
        title: 'Please select a size',
        variant: 'destructive',
      });
      return;
    }

    if (product.stock === 0) {
      toast({
        title: 'Out of stock',
        variant: 'destructive',
      });
      return;
    }

    addToCart({
      productId: product._id,
      name: product.name,
      price: product.price,
      image: product.images[0],
      size: selectedSize,
      stock: product.stock,
    });

    toast({
      title: 'Added to cart',
      description: `${product.name} has been added to your cart`,
    });
  };

  const handleToggleWishlist = async () => {
    if (!product) return;

    toggleWishlist(product._id);

    if (isCustomerSession(session)) {
      try {
        if (!isInWishlist) {
          await fetch('/api/wishlist', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ productId: product._id }),
          });
        } else {
          await fetch(`/api/wishlist?productId=${product._id}`, {
            method: 'DELETE',
          });
        }
      } catch (error) {
        console.error('Wishlist sync error:', error);
        toggleWishlist(product._id);
      }
    }

    toast({
      title: isInWishlist ? 'Removed from wishlist' : 'Added to wishlist',
    });
  };

  if (loading) {
    return (
      <div className="container mx-auto px-4 py-8 md:py-10">
        <div className="grid md:grid-cols-2 gap-6 md:gap-8">
          <div className="aspect-[4/5] rounded-xl bg-muted animate-pulse border border-border" />
          <div className="space-y-5">
            <div className="h-6 w-32 rounded-lg bg-muted animate-pulse" />
            <div className="h-8 w-3/4 rounded-lg bg-muted animate-pulse" />
            <div className="h-10 w-1/2 rounded-lg bg-muted animate-pulse" />
            <div className="h-20 rounded-lg bg-muted animate-pulse" />
          </div>
        </div>
      </div>
    );
  }

  if (!product) {
    return null;
  }

  const discountPercent = product.compareAtPrice
    ? Math.round(((product.compareAtPrice - product.price) / product.compareAtPrice) * 100)
    : 0;

  return (
    <div className="container mx-auto px-4 py-6 md:py-10 pb-28 md:pb-10">
      <div className="grid md:grid-cols-2 gap-6 md:gap-8 items-start">
        {/* Images */}
        <div className="space-y-3 w-full max-w-md md:max-w-full">
          <div className="relative w-full aspect-[4/5] max-h-[400px] md:max-h-[420px] rounded-xl overflow-hidden bg-muted shadow border border-border">
            <Image
              src={product.images[selectedImage]}
              alt={product.name}
              fill
              className="object-cover object-top"
              priority
              sizes="(max-width: 768px) 100vw, 50vw"
            />
            {discountPercent > 0 && (
              <Badge className="absolute top-2 left-2 rounded-md bg-primary text-primary-foreground text-xs font-semibold">
                -{discountPercent}%
              </Badge>
            )}
          </div>
          {product.images.length > 1 && (
            <div className="flex gap-2 overflow-x-auto pb-1 scrollbar-hide">
              {product.images.map((image, index) => (
                <button
                  key={index}
                  type="button"
                  onClick={() => setSelectedImage(index)}
                  className={`relative aspect-square w-16 shrink-0 rounded-lg overflow-hidden border-2 transition-all ${selectedImage === index ? 'border-primary ring-2 ring-primary/20' : 'border-border'
                    }`}
                >
                  <Image src={image} alt="" fill className="object-cover object-top" sizes="64px" />
                </button>
              ))}
            </div>
          )}
        </div>

        {/* Product Info */}
        <div className="space-y-5">
          {product.category && (
            <Badge variant="secondary" className="rounded-lg capitalize border-border">
              {product.category}
            </Badge>
          )}
          <h1 className="font-heading text-2xl md:text-3xl font-semibold tracking-tight">{product.name}</h1>

          <div className="flex items-center gap-1.5 mt-1">
            {reviewStats.total > 0 ? (
              <>
                <Star className="h-4 w-4 fill-amber-400 text-amber-400" />
                <span className="text-sm font-semibold">{reviewStats.avg}</span>
                <span className="text-sm text-muted-foreground">({reviewStats.total} review{reviewStats.total !== 1 ? 's' : ''})</span>
              </>
            ) : (
              <>
                <Star className="h-4 w-4 fill-amber-400 text-amber-400" />
                <span className="text-sm text-muted-foreground">No reviews yet</span>
              </>
            )}
          </div>

          <div className="flex items-center gap-3">
            <span className="text-2xl font-semibold">{formatPrice(product.price)}</span>
            {product.compareAtPrice && (
              <span className="text-lg text-muted-foreground line-through">
                {formatPrice(product.compareAtPrice)}
              </span>
            )}
          </div>

          <Separator className="bg-border" />

          <div>
            <h3 className="font-heading font-semibold mb-2 text-sm uppercase tracking-wide text-muted-foreground">Description</h3>
            <p className="text-muted-foreground text-sm leading-relaxed">{product.description}</p>
          </div>

          <div>
            <h3 className="font-heading font-semibold mb-3 text-sm uppercase tracking-wide text-muted-foreground">Select Size</h3>
            <div className="flex flex-wrap gap-2">
              {product.sizes.map((size) => (
                <Button
                  key={size}
                  variant={selectedSize === size ? 'default' : 'outline'}
                  size="sm"
                  className="rounded-lg min-w-[44px] border-border"
                  onClick={() => setSelectedSize(size)}
                >
                  {size}
                </Button>
              ))}
            </div>
          </div>

          <div>
            <h3 className="font-heading font-semibold mb-2 text-sm uppercase tracking-wide text-muted-foreground">Colors</h3>
            <div className="flex flex-wrap gap-2">
              {product.colors.map((color) => (
                <Badge key={color} variant="outline" className="rounded-lg border-border">
                  {color}
                </Badge>
              ))}
            </div>
          </div>

          <div>
            {product.stock > 0 ? (
              <Badge variant="secondary" className="rounded-lg border-border">In Stock ({product.stock})</Badge>
            ) : (
              <Badge variant="destructive" className="rounded-lg">Out of Stock</Badge>
            )}
          </div>

          {/* Desktop Actions */}
          <div className="hidden md:flex gap-3 pt-2">
            <Button
              onClick={handleAddToCart}
              disabled={product.stock === 0}
              className="flex-1 rounded-lg h-12"
              size="lg"
            >
              <ShoppingCart className="mr-2 h-5 w-5" />
              Add to bag
            </Button>
            <Button
              onClick={handleToggleWishlist}
              variant="outline"
              size="lg"
              className="rounded-lg h-12 border-border"
            >
              <Heart className={`h-5 w-5 ${isInWishlist ? 'fill-rose-500 text-rose-500' : ''}`} />
            </Button>
          </div>
        </div>
      </div>

      {/* Product Reviews */}
      <ProductReviews productId={product._id} />

      {/* Sticky bottom CTA - Mobile only */}
      <div className="md:hidden fixed bottom-16 left-0 right-0 z-40 p-4 bg-card border-t border-border shadow-lg safe-area-pb">
        <div className="container mx-auto flex gap-3">
          <Button
            onClick={handleToggleWishlist}
            variant="outline"
            size="lg"
            className="rounded-lg shrink-0 h-12 px-4 border-border"
          >
            <Heart className={`h-5 w-5 ${isInWishlist ? 'fill-rose-500 text-rose-500' : ''}`} />
          </Button>
          <Button
            onClick={handleAddToCart}
            disabled={product.stock === 0}
            className="flex-1 rounded-lg h-12 text-base font-semibold"
            size="lg"
          >
            <ShoppingCart className="mr-2 h-5 w-5" />
            Add to bag · {formatPrice(product.price)}
          </Button>
        </div>
      </div>
    </div>
  );
}

'use client';

import { Suspense, useEffect, useState } from 'react';
import { useSearchParams } from 'next/navigation';
import ProductCard from '@/components/ProductCard';
import FilterSidebar, { FilterState, type CategoryOption } from '@/components/FilterSidebar';
import Pagination from '@/components/Pagination';
import { ProductWithId, PaginatedResponse } from '@/types';
import { Button } from '@/components/ui/button';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import {
  BottomSheet,
  BottomSheetContent,
  BottomSheetTrigger,
} from '@/components/ui/bottom-sheet';
import { SlidersHorizontal, X, ArrowUpDown } from 'lucide-react';

const PRICE_MAX = 10000;

const DEFAULT_FILTERS: FilterState = {
  category: [],
  minPrice: 0,
  maxPrice: PRICE_MAX,
  sizes: [],
  colors: [],
  minDiscount: 0,
};

const SORT_OPTIONS = [
  { value: 'newest', label: 'Recommended' },
  { value: 'price-asc', label: 'Price: Low to High' },
  { value: 'price-desc', label: 'Price: High to Low' },
  { value: 'name', label: 'Name: A to Z' },
];

function ProductsContent() {
  const searchParams = useSearchParams();

  const [products, setProducts] = useState<ProductWithId[]>([]);
  const [loading, setLoading] = useState(true);
  const [pagination, setPagination] = useState({ page: 1, limit: 12, total: 0, totalPages: 0 });
  const [filters, setFilters] = useState<FilterState>(() => {
    const defaultCat = searchParams.get('categoryId');
    return {
      ...DEFAULT_FILTERS,
      category: defaultCat ? [defaultCat] : []
    };
  });
  const [sort, setSort] = useState('newest');
  const [mobileSheetOpen, setMobileSheetOpen] = useState(false);
  const [mobileSortOpen, setMobileSortOpen] = useState(false);
  const [categories, setCategories] = useState<CategoryOption[]>([]);

  useEffect(() => {
    fetch('/api/categories')
      .then((r) => r.json())
      .then((d) => setCategories(Array.isArray(d) ? d : []))
      .catch(() => { });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const categoryLabels: Record<string, string> = Object.fromEntries(
    categories.map((c) => [c._id, c.name])
  );

  const activeFilterCount =
    filters.category.length + filters.sizes.length + filters.colors.length +
    (filters.minPrice > 0 || filters.maxPrice < PRICE_MAX ? 1 : 0) +
    (filters.minDiscount > 0 ? 1 : 0);

  useEffect(() => {
    fetchProducts();
  }, [searchParams, filters, sort, pagination.page]);

  const fetchProducts = async () => {
    setLoading(true);
    const params = new URLSearchParams();
    params.set('page', pagination.page.toString());
    params.set('limit', pagination.limit.toString());
    params.set('sort', sort);

    const search = searchParams.get('search');
    if (search) params.set('search', search);

    // Use selected filters.category as the definitive source for category filtering
    if (filters.category.length > 0) {
      params.set('categoryId', filters.category.join(','));
    } else {
      const urlCategory = searchParams.get('category');
      if (urlCategory) params.set('category', urlCategory);
    }

    const featured = searchParams.get('featured');
    if (featured) params.set('featured', featured);

    const bigSize = searchParams.get('bigSize');
    if (bigSize === 'true') params.set('bigSize', 'true');

    if (filters.minPrice > 0) params.set('minPrice', filters.minPrice.toString());
    if (filters.maxPrice < PRICE_MAX) params.set('maxPrice', filters.maxPrice.toString());
    if (filters.sizes.length > 0) params.set('size', filters.sizes.join(','));
    if (filters.colors.length > 0) params.set('color', filters.colors.join(','));
    if (filters.minDiscount > 0) params.set('minDiscount', filters.minDiscount.toString());

    try {
      const response = await fetch(`/api/products?${params.toString()}`);
      const data: PaginatedResponse<ProductWithId> = await response.json();
      setProducts(data.data);
      setPagination(data.pagination);
    } catch (error) {
      console.error('Failed to fetch products:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleFilterChange = (newFilters: FilterState) => {
    setFilters(newFilters);
    setPagination((p) => ({ ...p, page: 1 }));
  };

  const removeChip = (patch: Partial<FilterState>) =>
    handleFilterChange({ ...filters, ...patch });

  const isBigSize = searchParams.get('bigSize') === 'true';
  const sortLabel = SORT_OPTIONS.find((o) => o.value === sort)?.label ?? 'Recommended';

  return (
    <div className="container mx-auto px-4 py-6 md:py-8 pb-28 md:pb-8">
      <h1 className="font-heading text-2xl md:text-3xl font-semibold mb-6 tracking-tight">
        {isBigSize ? 'Big Size' : 'Shop Dresses'}
      </h1>
      {isBigSize && (
        <p className="text-muted-foreground mb-4 -mt-2">Dresses available in XL, XXL and beyond</p>
      )}

      <div className="flex gap-6 items-start">

        {/* ════════════════════════════════════════
            DESKTOP sidebar — no scroll, shows all
        ════════════════════════════════════════ */}
        <aside className="hidden md:block w-56 xl:w-64 shrink-0">
          <div className="rounded-xl border border-border bg-card shadow p-4">
            <FilterSidebar
              categories={categories}
              initialFilters={filters}
              onFilterChange={handleFilterChange}
            />
          </div>
        </aside>

        {/* ════════════════
            Main content
        ════════════════ */}
        <div className="flex-1 min-w-0">

          {/* ── Desktop top bar: count + Sort ── */}
          <div className="hidden md:flex items-center justify-between mb-4">
            <p className="text-sm text-muted-foreground font-medium">
              {loading ? 'Loading…' : `${pagination.total} products`}
            </p>
            <Select value={sort} onValueChange={(v) => { setSort(v); setPagination((p) => ({ ...p, page: 1 })); }}>
              <SelectTrigger className="w-[200px] h-10 border-border">
                <SelectValue placeholder="Sort by" />
              </SelectTrigger>
              <SelectContent>
                {SORT_OPTIONS.map((o) => (
                  <SelectItem key={o.value} value={o.value}>{o.label}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {/* ── Active filter chips (both screens) ── */}
          {activeFilterCount > 0 && (
            <div className="flex flex-wrap items-center gap-2 mb-4">
              {filters.category.map((id) => (
                <button key={id}
                  onClick={() => removeChip({ category: filters.category.filter((c) => c !== id) })}
                  className="inline-flex items-center gap-1.5 rounded-[10px] bg-primary/10 border border-primary/20 px-3 py-1 text-xs font-medium text-primary hover:bg-primary/20 transition-colors">
                  {categoryLabels[id] ?? id} <X className="h-3 w-3" />
                </button>
              ))}
              {(filters.minPrice > 0 || filters.maxPrice < PRICE_MAX) && (
                <button onClick={() => removeChip({ minPrice: 0, maxPrice: PRICE_MAX })}
                  className="inline-flex items-center gap-1.5 rounded-[10px] bg-primary/10 border border-primary/20 px-3 py-1 text-xs font-medium text-primary hover:bg-primary/20 transition-colors">
                  ₹{filters.minPrice.toLocaleString('en-IN')} – ₹{filters.maxPrice.toLocaleString('en-IN')}
                  <X className="h-3 w-3" />
                </button>
              )}
              {filters.sizes.map((size) => (
                <button key={size}
                  onClick={() => removeChip({ sizes: filters.sizes.filter((s) => s !== size) })}
                  className="inline-flex items-center gap-1.5 rounded-[10px] bg-primary/10 border border-primary/20 px-3 py-1 text-xs font-medium text-primary hover:bg-primary/20 transition-colors">
                  Size: {size} <X className="h-3 w-3" />
                </button>
              ))}
              {filters.colors.map((color) => (
                <button key={color}
                  onClick={() => removeChip({ colors: filters.colors.filter((c) => c !== color) })}
                  className="inline-flex items-center gap-1.5 rounded-[10px] bg-primary/10 border border-primary/20 px-3 py-1 text-xs font-medium text-primary hover:bg-primary/20 transition-colors">
                  {color} <X className="h-3 w-3" />
                </button>
              ))}
              {filters.minDiscount > 0 && (
                <button onClick={() => removeChip({ minDiscount: 0 })}
                  className="inline-flex items-center gap-1.5 rounded-[10px] bg-primary/10 border border-primary/20 px-3 py-1 text-xs font-medium text-primary hover:bg-primary/20 transition-colors">
                  {filters.minDiscount}%+ off <X className="h-3 w-3" />
                </button>
              )}
              <button onClick={() => handleFilterChange(DEFAULT_FILTERS)}
                className="inline-flex items-center gap-1.5 rounded-[10px] border border-border px-3 py-1 text-xs font-medium text-muted-foreground hover:text-destructive hover:border-destructive/40 transition-colors">
                Clear All <X className="h-3 w-3" />
              </button>
            </div>
          )}

          {/* Loading skeleton */}
          {loading && (
            <div className="grid grid-cols-2 lg:grid-cols-12 gap-4 md:gap-5">
              {[...Array(7)].map((_, i) => (
                <div key={i} className={`rounded-xl overflow-hidden border border-border bg-card shadow col-span-1 ${i < 3 ? 'lg:col-span-4' : 'lg:col-span-3'}`}>
                  <div className="aspect-square bg-muted animate-pulse" />
                  <div className="p-3 space-y-2">
                    <div className="h-3 w-3/4 rounded bg-muted animate-pulse" />
                    <div className="h-3 w-1/2 rounded bg-muted animate-pulse" />
                    <div className="h-9 rounded-lg bg-muted animate-pulse" />
                  </div>
                </div>
              ))}
            </div>
          )}

          {/* Products grid */}
          {!loading && products.length > 0 && (
            <>
              <div className="grid grid-cols-2 lg:grid-cols-12 gap-4 md:gap-5">
                {products.map((product, i) => (
                  <div key={product._id} className={`col-span-1 ${i < 3 ? 'lg:col-span-4' : 'lg:col-span-3'}`}>
                    <ProductCard product={product} />
                  </div>
                ))}
              </div>
              {pagination.totalPages > 1 && (
                <Pagination
                  currentPage={pagination.page}
                  totalPages={pagination.totalPages}
                  onPageChange={(page) => {
                    setPagination((p) => ({ ...p, page }));
                    window.scrollTo({ top: 0, behavior: 'smooth' });
                  }}
                />
              )}
            </>
          )}

          {/* Empty */}
          {!loading && products.length === 0 && (
            <div className="text-center py-20 rounded-xl border border-border bg-card shadow">
              <p className="text-muted-foreground mb-4 font-medium">No products found</p>
              <Button onClick={() => handleFilterChange(DEFAULT_FILTERS)}>Clear Filters</Button>
            </div>
          )}
        </div>
      </div>

      {/* ════════════════════════════════════════
          MOBILE — sticky "Filter & Sort" bar
      ════════════════════════════════════════ */}
      <div className="md:hidden fixed bottom-16 left-0 right-0 z-40 flex border-t border-border bg-background shadow-lg">
        {/* Filter */}
        <BottomSheet open={mobileSheetOpen} onOpenChange={setMobileSheetOpen}>
          <BottomSheetTrigger asChild>
            <button
              type="button"
              className="flex flex-1 items-center justify-center gap-2 py-3.5 text-sm font-semibold text-foreground border-r border-border hover:bg-muted/50 transition-colors"
            >
              <SlidersHorizontal className="h-4 w-4" />
              Filter
              {activeFilterCount > 0 && (
                <span className="rounded-full bg-primary text-primary-foreground min-w-[18px] h-[18px] flex items-center justify-center text-xs font-bold px-1">
                  {activeFilterCount}
                </span>
              )}
            </button>
          </BottomSheetTrigger>
          <BottomSheetContent>
            {mobileSheetOpen && (
              <FilterSidebar
                categories={categories}
                initialFilters={filters}
                inDrawer
                onFilterChange={(f) => {
                  handleFilterChange(f);
                  setMobileSheetOpen(false);
                }}
              />
            )}
          </BottomSheetContent>
        </BottomSheet>

        {/* Sort */}
        <BottomSheet open={mobileSortOpen} onOpenChange={setMobileSortOpen}>
          <BottomSheetTrigger asChild>
            <button
              type="button"
              className="flex flex-1 items-center justify-center gap-2 py-3.5 text-sm font-semibold text-foreground hover:bg-muted/50 transition-colors"
            >
              <ArrowUpDown className="h-4 w-4" />
              Sort
              {sort !== 'newest' && (
                <span className="rounded-full bg-primary/15 text-primary min-w-[6px] h-[6px] inline-block" />
              )}
            </button>
          </BottomSheetTrigger>
          <BottomSheetContent>
            <div className="py-2">
              <p className="text-xs font-semibold uppercase tracking-widest text-muted-foreground px-1 mb-3">Sort By</p>
              {SORT_OPTIONS.map((opt) => (
                <button
                  key={opt.value}
                  type="button"
                  onClick={() => {
                    setSort(opt.value);
                    setPagination((p) => ({ ...p, page: 1 }));
                    setMobileSortOpen(false);
                  }}
                  className={`flex w-full items-center justify-between px-2 py-3.5 text-sm rounded-lg transition-colors ${sort === opt.value
                    ? 'text-primary font-semibold bg-primary/8'
                    : 'text-foreground hover:bg-muted/60'
                    }`}
                >
                  {opt.label}
                  {sort === opt.value && (
                    <svg className="h-4 w-4 text-primary" fill="none" viewBox="0 0 16 16">
                      <path d="M3 8l3.5 3.5 6.5-7" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
                    </svg>
                  )}
                </button>
              ))}
            </div>
          </BottomSheetContent>
        </BottomSheet>
      </div>
    </div>
  );
}

export default function ProductsPage() {
  return (
    <Suspense fallback={
      <div className="container mx-auto px-4 py-6">
        <div className="h-8 w-32 rounded bg-muted animate-pulse mb-6" />
        <div className="flex gap-6">
          <div className="hidden md:block w-56 xl:w-64 shrink-0 rounded-xl border border-border bg-card animate-pulse" style={{ height: 600 }} />
          <div className="flex-1 grid grid-cols-2 lg:grid-cols-12 gap-4 xl:gap-5">
            {[...Array(7)].map((_, i) => <div key={i} className={`aspect-square rounded-xl bg-muted animate-pulse col-span-1 ${i < 3 ? 'lg:col-span-4' : 'lg:col-span-3'}`} />)}
          </div>
        </div>
      </div>
    }>
      <ProductsContent />
    </Suspense>
  );
}

'use client';

import { useEffect, useState } from 'react';
import { useSession } from 'next-auth/react';
import { isCustomerSession } from '@/lib/customerSession';
import { useWishlistStore } from '@/store/wishlistStore';
import { ProductWithId } from '@/types';
import ProductCard from '@/components/ProductCard';
import { Button } from '@/components/ui/button';
import Link from 'next/link';
import { Heart, Loader2 } from 'lucide-react';

export default function WishlistPage() {
  const { data: session } = useSession();
  const wishlistIds = useWishlistStore((state) => state.items);
  const setWishlistItems = useWishlistStore((state) => state.setItems);
  
  const [products, setProducts] = useState<ProductWithId[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchWishlist();
  }, [session]);

  const fetchWishlist = async () => {
    setLoading(true);

    if (isCustomerSession(session)) {
      // Fetch from API if logged in as customer (admin is separate)
      try {
        const response = await fetch('/api/wishlist');
        if (response.ok) {
          const data = await response.json();
          const productIds = data.productIds.map((p: any) => p._id);
          setWishlistItems(productIds);
          setProducts(data.productIds);
        }
      } catch (error) {
        console.error('Failed to fetch wishlist:', error);
      }
    } else {
      // Fetch products from localStorage IDs
      if (wishlistIds.length > 0) {
        try {
          const productPromises = wishlistIds.map((id) =>
            fetch(`/api/products/${id}`).then((r) => r.json())
          );
          const productsData = await Promise.all(productPromises);
          setProducts(productsData.filter((p) => p && !p.error));
        } catch (error) {
          console.error('Failed to fetch wishlist products:', error);
        }
      }
    }

    setLoading(false);
  };

  if (loading) {
    return (
      <div className="container mx-auto px-4 py-12 pb-24 md:pb-12">
        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4 md:gap-6">
          {[...Array(6)].map((_, i) => (
            <div key={i} className="rounded-xl overflow-hidden border border-border bg-card shadow">
              <div className="aspect-[4/5] bg-muted animate-pulse" />
              <div className="p-3 md:p-4 space-y-2">
                <div className="h-3 w-3/4 rounded bg-muted animate-pulse" />
                <div className="h-3 w-1/2 rounded bg-muted animate-pulse" />
              </div>
            </div>
          ))}
        </div>
      </div>
    );
  }

  if (products.length === 0) {
    return (
      <div className="container mx-auto px-4 py-16 md:py-20 pb-24 md:pb-20">
        <div className="text-center space-y-5 max-w-sm mx-auto">
          <div className="w-20 h-20 mx-auto rounded-xl bg-muted border border-border flex items-center justify-center">
            <Heart className="h-10 w-10 text-muted-foreground" />
          </div>
          <h1 className="font-heading text-2xl font-semibold tracking-tight">Your wishlist is empty</h1>
          <p className="text-muted-foreground text-sm">
            Save your favorite items and move them to cart anytime
          </p>
          <Button className="rounded-lg w-full" size="lg" asChild>
            <Link href="/products">Shop now</Link>
          </Button>
        </div>
      </div>
    );
  }

  return (
    <div className="container mx-auto px-4 py-6 md:py-8 pb-24 md:pb-8">
      <h1 className="font-heading text-2xl md:text-3xl font-semibold mb-2 tracking-tight">My Wishlist</h1>
      <p className="text-sm text-muted-foreground mb-6">
        {products.length} {products.length === 1 ? 'item' : 'items'}
      </p>
      <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4 md:gap-6">
        {products.map((product) => (
          <ProductCard key={product._id} product={product} />
        ))}
      </div>
    </div>
  );
}
